import { readFileSync, existsSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { Tokenizer } from "../src/tokenizer";

// Fixtures are generated by training/scripts/js_fixtures.py from validation text and are not published; the tests skip without them.
const FIX = new URL("./fixtures/", import.meta.url);
const MODELS = process.env.PII_MODELS ?? new URL("./models/", import.meta.url).pathname;
const have = existsSync(new URL("tokenize.jsonl", FIX)) && existsSync(`${MODELS}/pii-nano/tokenizer.web.json`);

describe.skipIf(!have)("tokenizer parity with Hugging Face tokenizers", () => {
  // vitest runs this callback while collecting even when the suite is skipped, so every read is guarded by `have`
  const tok = have ? new Tokenizer(JSON.parse(readFileSync(`${MODELS}/pii-nano/tokenizer.web.json`, "utf8"))) : null!;
  const rows = have
    ? readFileSync(new URL("tokenize.jsonl", FIX), "utf8").trim().split("\n").map((l) => JSON.parse(l))
    : [];
  // Python offsets count code points; JavaScript strings count UTF-16 units
  for (const r of rows) {
    const units: number[] = [0];
    for (const ch of r.text) units.push(units[units.length - 1] + ch.length);
    r.offsets = r.offsets.map(([s, e]: [number, number]) => [units[s], units[e]]);
  }

  it("produces the same ids", () => {
    const bad = rows.filter((r) => JSON.stringify(tok.encode(r.text).ids) !== JSON.stringify(r.ids));
    for (const r of bad.slice(0, 5)) console.log(JSON.stringify(r.text).slice(0, 120), r.ids.slice(0, 20), tok.encode(r.text).ids.slice(0, 20));
    expect(bad.length).toBe(0);
  });

  it("produces the same offsets", () => {
    const bad = rows.filter((r) => JSON.stringify(tok.encode(r.text).offsets) !== JSON.stringify(r.offsets));
    for (const r of bad.slice(0, 5)) {
      const e = tok.encode(r.text);
      const k = e.offsets.findIndex((o, i) => JSON.stringify(o) !== JSON.stringify(r.offsets[i]));
      console.log(JSON.stringify(r.text).slice(0, 80), k, r.offsets.slice(Math.max(0, k - 1), k + 2), e.offsets.slice(Math.max(0, k - 1), k + 2));
    }
    expect(bad.length).toBeLessThanOrEqual(3);
  });
});
